import React from 'react';
import { questions } from '../data/questions';

const Summary = ({ answers }) => {
  // Calculate total cost
  const totalCost = Object.values(answers).reduce((sum, answer) => sum + (answer?.cost || 0), 0);

  // Group answers by tags
  const tagGroups = Object.values(answers).reduce((groups, answer) => {
    if (answer?.tags) {
      answer.tags.forEach(tag => {
        if (!groups[tag]) groups[tag] = [];
        groups[tag].push(answer);
      });
    }
    return groups;
  }, {});

  // Get dominant style
  const getDominantStyle = () => {
    const styleCounts = {
      traditional: tagGroups.traditional?.length || 0,
      modern: tagGroups.modern?.length || 0,
      minimal: tagGroups.minimal?.length || 0,
      luxury: tagGroups.luxury?.length || 0,
    };
    return Object.entries(styleCounts).reduce((a, b) => a[1] > b[1] ? a : b)[0];
  };

  const dominantStyle = getDominantStyle();

  const getStyleName = (style) => {
    switch(style) {
      case 'traditional': return 'แบบดั้งเดิม';
      case 'modern': return 'แบบสมัยใหม่';
      case 'minimal': return 'แบบเรียบง่าย';
      case 'luxury': return 'แบบหรูหรา';
      default: return '';
    }
  };

  return (
    <div className="min-h-screen bg-gray-900 text-white p-6 animate-fade-in">
      <div className="max-w-4xl mx-auto space-y-8">
        {/* Header */}
        <div className="text-center space-y-4 animate-slide-up">
          <h1 className="text-4xl font-bold text-red-500">สรุปแผนงานศพของคุณ</h1>
          <p className="text-xl text-gray-300">สไตล์ {getStyleName(dominantStyle)}</p>
        </div>

        {/* Cost Summary */}
        <div className="bg-gray-800 rounded-xl p-6 shadow-lg animate-slide-up" style={{ animationDelay: '0.2s' }}>
          <h2 className="text-2xl font-semibold mb-4 text-red-400">งบประมาณรวม</h2>
          <p className="text-4xl font-bold text-white">{totalCost.toLocaleString()} บาท</p>
        </div>

        {/* Style Highlights */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 animate-slide-up" style={{ animationDelay: '0.4s' }}>
          {Object.entries(tagGroups).map(([tag, items]) => (
            <div key={tag} className="bg-gray-800 rounded-xl p-6 shadow-lg">
              <h3 className="text-xl font-semibold mb-4 text-red-400">
                {getStyleName(tag)}
              </h3>
              <ul className="space-y-2">
                {items.slice(0, 3).map((item, index) => (
                  <li key={index} className="text-gray-300">
                    {typeof item.text === 'string' ? item.text : ''}
                  </li>
                ))}
              </ul>
            </div>
          ))}
        </div>

        {/* Key Decisions */}
        <div className="bg-gray-800 rounded-xl p-6 shadow-lg animate-slide-up" style={{ animationDelay: '0.6s' }}>
          <h2 className="text-2xl font-semibold mb-4 text-red-400">การตัดสินใจสำคัญ</h2>
          <div className="space-y-4">
            {Object.entries(answers).map(([questionId, answer]) => {
              const question = questions[questionId];
              if (!question || !answer) return null;
              
              return (
                <div key={questionId} className="border-l-4 border-red-500 pl-4">
                  <h3 className="font-medium text-gray-300">
                    {typeof question.text === 'string' ? question.text : ''}
                  </h3>
                  <p className="text-white mt-1">
                    {typeof answer.text === 'string' ? answer.text : ''}
                  </p>
                </div>
              );
            })}
          </div>
        </div>

        {/* Footer */}
        <div className="text-center text-gray-400 animate-fade-in-delay">
          <p className="italic">"การวางแผนงานศพคือการแสดงความรักครั้งสุดท้าย"</p>
        </div>
      </div>
    </div>
  );
};

export default Summary;
